"""
Tests for the sep (Source Extractor Python) package used in lcogtsnpipe.

sep is used by PyZOGY.util to:
- Estimate the image background: sep.Background()
- Extract sources: sep.extract()
- Control extraction pixel stack: sep.set_extract_pixstack()

These tests exercise those exact functions with synthetic image data.

Additional coverage added:
  - TestSepBackgroundAdvanced: bkg.subfrom(), bkg.globalback/globalrms attributes, bkg(x,y)
  - TestSepExtractFields: all structured-array fields present (cxx, cyy, cxy, peak, flag…)
  - TestSepExtractEdgeCases: empty image, gain kwarg, minarea kwarg, deblend params
  - TestSepSumCircle: aperture photometry flux/fluxerr/flag, flag constants
  - TestSepSumEllipse: ellipse aperture matching extract shape parameters
  - TestSepSumCircann: annular aperture (sky background estimation)
  - TestSepKronRadius: Kron radius computation from source shape params
  - TestSepFluxRadius: half-light radius / flux_radius()
  - TestSepWinpos: windowed centroid refinement
  - TestSepEllipseGeometry: ellipse_coeffs / ellipse_axes roundtrip
  - TestSepGetSetPixstack: get_extract_pixstack / set_extract_pixstack roundtrip
  - TestSepFlagConstants: APER_TRUNC, APER_HASMASKED, OBJ_MERGED, etc.
  - TestPyZOGYUtilPattern: byteswap().newbyteorder() background pattern from PyZOGY.util
"""
import numpy as np
import pytest

pytestmark = pytest.mark.unit


def _make_image(nstars: int = 5, noise_sigma: float = 5.0,
                star_flux: float = 5000.0, shape: tuple = (64, 64),
                seed: int = 42) -> np.ndarray:
    """Create a float64 synthetic image with Gaussian stars and Poisson-ish noise."""
    rng = np.random.default_rng(seed)
    img = rng.normal(100.0, noise_sigma, shape)
    ny, nx = shape
    for _ in range(nstars):
        cx = rng.integers(10, nx - 10)
        cy = rng.integers(10, ny - 10)
        # 2-D Gaussian PSF
        yy, xx = np.mgrid[0:ny, 0:nx]
        sig = 2.0
        img += star_flux * np.exp(-((xx - cx) ** 2 + (yy - cy) ** 2) / (2 * sig ** 2))
    return img.astype(np.float64)


def _c_contiguous(img: np.ndarray) -> np.ndarray:
    """Return a native byte order, C-contiguous float64 copy as sep requires.

    numpy 2.x removed ndarray.newbyteorder(); use dtype.newbyteorder() instead.
    Since our synthetic data is generated by numpy (native byte order already),
    this is essentially a no-op but ensures sep compatibility.
    """
    return np.ascontiguousarray(img, dtype=img.dtype.newbyteorder('='))


# ---------------------------------------------------------------------------
# Import
# ---------------------------------------------------------------------------

class TestSepImport:
    def test_sep_importable(self):
        import sep
        assert hasattr(sep, "__version__")

    def test_key_functions_exist(self):
        import sep
        assert callable(sep.Background)
        assert callable(sep.extract)
        assert callable(sep.set_extract_pixstack)


# ---------------------------------------------------------------------------
# sep.Background — background estimation (mirrors PyZOGY.util.py line 38)
# ---------------------------------------------------------------------------

class TestSepBackground:
    def test_background_estimable(self):
        import sep
        img = _c_contiguous(_make_image())
        bkg = sep.Background(img)
        assert bkg is not None

    def test_background_rms_positive(self):
        import sep
        img = _c_contiguous(_make_image(noise_sigma=5.0))
        bkg = sep.Background(img)
        assert bkg.globalrms > 0.0

    def test_background_level_near_sky(self):
        import sep
        img = _c_contiguous(_make_image())
        bkg = sep.Background(img)
        # sky background should be close to 100 (our bias level)
        assert abs(bkg.globalback - 100.0) < 20.0

    def test_background_subfrom_reduces_mean(self):
        import sep
        img = _c_contiguous(_make_image())
        bkg = sep.Background(img)
        sub = img - bkg.back()
        # after subtraction mean should be close to 0 (minus star flux)
        assert abs(np.median(sub)) < 10.0

    def test_background_back_shape(self):
        import sep
        shape = (64, 64)
        img = _c_contiguous(_make_image(shape=shape))
        bkg = sep.Background(img)
        assert bkg.back().shape == shape

    def test_background_rms_shape(self):
        import sep
        shape = (64, 64)
        img = _c_contiguous(_make_image(shape=shape))
        bkg = sep.Background(img)
        assert bkg.rms().shape == shape


# ---------------------------------------------------------------------------
# sep.extract — source extraction (mirrors PyZOGY.util.py lines 104-105)
# ---------------------------------------------------------------------------

class TestSepExtract:
    def test_extract_finds_sources(self):
        import sep
        img = _c_contiguous(_make_image(nstars=5, star_flux=5000.0))
        bkg = sep.Background(img)
        sub = (img - bkg.back()).astype(np.float64)
        sources = sep.extract(np.ascontiguousarray(sub), thresh=5.0, err=bkg.globalrms)
        assert len(sources) >= 1

    def test_extract_returns_structured_array(self):
        import sep
        img = _c_contiguous(_make_image(nstars=3))
        bkg = sep.Background(img)
        sub = (img - bkg.back()).astype(np.float64)
        sources = sep.extract(np.ascontiguousarray(sub), thresh=5.0, err=bkg.globalrms)
        assert "x" in sources.dtype.names
        assert "y" in sources.dtype.names

    def test_extract_source_positions_in_bounds(self):
        import sep
        shape = (64, 64)
        img = _c_contiguous(_make_image(nstars=5, shape=shape))
        bkg = sep.Background(img)
        sub = (img - bkg.back()).astype(np.float64)
        sources = sep.extract(np.ascontiguousarray(sub), thresh=5.0, err=bkg.globalrms)
        if len(sources) > 0:
            assert np.all(sources["x"] >= 0)
            assert np.all(sources["x"] < shape[1])
            assert np.all(sources["y"] >= 0)
            assert np.all(sources["y"] < shape[0])

    def test_extract_high_thresh_finds_fewer(self):
        """Higher threshold → fewer extracted sources."""
        import sep
        img = _c_contiguous(_make_image(nstars=10, star_flux=5000.0))
        bkg = sep.Background(img)
        sub = (img - bkg.back()).astype(np.float64)
        n_low = len(sep.extract(np.ascontiguousarray(sub), thresh=3.0, err=bkg.globalrms))
        n_high = len(sep.extract(np.ascontiguousarray(sub), thresh=50.0, err=bkg.globalrms))
        assert n_low >= n_high

    def test_extract_with_mask(self):
        import sep
        shape = (64, 64)
        img = _c_contiguous(_make_image(nstars=5, shape=shape))
        bkg = sep.Background(img)
        sub = (img - bkg.back()).astype(np.float64)
        mask = np.zeros(shape, dtype=bool)
        mask[:32, :] = True  # mask top half
        sources = sep.extract(np.ascontiguousarray(sub), thresh=5.0,
                              err=bkg.globalrms,
                              mask=np.ascontiguousarray(mask))
        # all sources should be in unmasked bottom half
        if len(sources) > 0:
            assert np.all(sources["y"] >= 32)

    def test_extract_has_flux_field(self):
        import sep
        img = _c_contiguous(_make_image(nstars=3, star_flux=10000.0))
        bkg = sep.Background(img)
        sub = (img - bkg.back()).astype(np.float64)
        sources = sep.extract(np.ascontiguousarray(sub), thresh=5.0, err=bkg.globalrms)
        assert "flux" in sources.dtype.names

    def test_extract_with_err_map(self):
        import sep
        img = _c_contiguous(_make_image(nstars=5))
        bkg = sep.Background(img)
        err_map = np.full(img.shape, bkg.globalrms)
        sub = (img - bkg.back()).astype(np.float64)
        sources = sep.extract(np.ascontiguousarray(sub), thresh=5.0,
                              err=np.ascontiguousarray(err_map))
        assert isinstance(sources, np.ndarray)


