# ---------------------------------------------------------------------------
# sep.Background — advanced attributes and methods
# ---------------------------------------------------------------------------

class TestSepBackgroundAdvanced:
    """Additional Background attributes used in the PyZOGY.util pattern."""

    def test_globalback_attribute(self):
        import sep
        img = _c_contiguous(_make_image())
        bkg = sep.Background(img)
        assert isinstance(bkg.globalback, float)

    def test_globalrms_attribute(self):
        import sep
        img = _c_contiguous(_make_image(noise_sigma=3.0))
        bkg = sep.Background(img)
        assert isinstance(bkg.globalrms, float)
        assert bkg.globalrms > 0.0

    def test_subfrom_modifies_inplace(self):
        """bkg.subfrom(data) subtracts background in-place."""
        import sep
        img = _c_contiguous(_make_image())
        bkg = sep.Background(img)
        data = img.copy()
        bkg.subfrom(data)
        # median of background-subtracted image should be near 0
        assert abs(np.median(data)) < 15.0

    def test_back_array_values_near_sky(self):
        """bkg.back() values should be close to the input sky level (100)."""
        import sep
        img = _c_contiguous(_make_image())
        bkg = sep.Background(img)
        back = bkg.back()
        assert np.median(back) == pytest.approx(100.0, abs=20.0)

    def test_rms_array_positive(self):
        import sep
        img = _c_contiguous(_make_image(noise_sigma=5.0))
        bkg = sep.Background(img)
        assert np.all(bkg.rms() > 0)

    def test_background_byteswap_pattern(self):
        """PyZOGY.util ensures native byte order before passing to sep.Background.
        In numpy 2.x the correct idiom is astype(dtype.newbyteorder('=')).
        """
        import sep
        rng = np.random.default_rng(77)
        # Create big-endian array to simulate non-native byte order
        data = rng.normal(100.0, 5.0, (32, 32)).astype(np.dtype('>f8'))
        # Convert to native byte order (numpy 2.x compatible)
        safe = np.ascontiguousarray(data.astype(data.dtype.newbyteorder('=')))
        bkg = sep.Background(safe)
        assert bkg.globalrms > 0.0


# ---------------------------------------------------------------------------
# sep.extract — structured-array fields
# ---------------------------------------------------------------------------

class TestSepExtractFields:
    """Verify all expected structured-array fields are present in the output."""

    def _extract(self):
        import sep
        img = _c_contiguous(_make_image(nstars=3, star_flux=10000.0))
        bkg = sep.Background(img)
        sub = np.ascontiguousarray((img - bkg.back()).astype(np.float64))
        return sep.extract(sub, thresh=5.0, err=bkg.globalrms)

    def test_has_x_y(self):
        sources = self._extract()
        assert "x" in sources.dtype.names
        assert "y" in sources.dtype.names

    def test_has_a_b_theta(self):
        sources = self._extract()
        assert "a" in sources.dtype.names
        assert "b" in sources.dtype.names
        assert "theta" in sources.dtype.names

    def test_has_cxx_cyy_cxy(self):
        sources = self._extract()
        assert "cxx" in sources.dtype.names
        assert "cyy" in sources.dtype.names
        assert "cxy" in sources.dtype.names

    def test_has_flux_and_peak(self):
        sources = self._extract()
        assert "flux" in sources.dtype.names
        assert "peak" in sources.dtype.names

    def test_has_npix(self):
        sources = self._extract()
        assert "npix" in sources.dtype.names
        assert np.all(sources["npix"] > 0)

    def test_has_flag(self):
        sources = self._extract()
        assert "flag" in sources.dtype.names

    def test_flux_positive_for_bright_stars(self):
        sources = self._extract()
        assert np.all(sources["flux"] > 0)

    def test_a_ge_b(self):
        """sep convention: a >= b (semi-major >= semi-minor axis)."""
        sources = self._extract()
        assert np.all(sources["a"] >= sources["b"] - 1e-6)


# ---------------------------------------------------------------------------
# sep.extract — edge cases
# ---------------------------------------------------------------------------

class TestSepExtractEdgeCases:
    """Edge-case behaviours: minarea, deblend, gain, empty result."""

    def test_very_high_thresh_returns_empty(self):
        import sep
        img = _c_contiguous(_make_image(nstars=5, star_flux=100.0))
        bkg = sep.Background(img)
        sub = np.ascontiguousarray((img - bkg.back()).astype(np.float64))
        sources = sep.extract(sub, thresh=1e6, err=bkg.globalrms)
        assert len(sources) == 0

    def test_minarea_filters_small_blobs(self):
        """minarea=20 should reject tiny blobs; minarea=5 should accept them."""
        import sep
        img = _c_contiguous(_make_image(nstars=5, star_flux=3000.0))
        bkg = sep.Background(img)
        sub = np.ascontiguousarray((img - bkg.back()).astype(np.float64))
        n_large = len(sep.extract(sub, thresh=3.0, err=bkg.globalrms, minarea=20))
        n_small = len(sep.extract(sub, thresh=3.0, err=bkg.globalrms, minarea=3))
        assert n_small >= n_large

    def test_gain_kwarg_accepted(self):
        """gain parameter adjusts Poisson noise estimate."""
        import sep
        img = _c_contiguous(_make_image(nstars=3))
        bkg = sep.Background(img)
        sub = np.ascontiguousarray((img - bkg.back()).astype(np.float64))
        sources = sep.extract(sub, thresh=5.0, err=bkg.globalrms, gain=1.5)
        assert isinstance(sources, np.ndarray)

    def test_deblend_nthresh_kwarg(self):
        import sep
        img = _c_contiguous(_make_image(nstars=3))
        bkg = sep.Background(img)
        sub = np.ascontiguousarray((img - bkg.back()).astype(np.float64))
        sources = sep.extract(sub, thresh=5.0, err=bkg.globalrms, deblend_nthresh=32)
        assert isinstance(sources, np.ndarray)

    def test_extract_with_rms_map(self):
        """err as a 2-D map (instead of scalar) is accepted by sep.extract."""
        import sep
        img = _c_contiguous(_make_image(nstars=3))
        bkg = sep.Background(img)
        err_map = np.ascontiguousarray(bkg.rms())
        sub = np.ascontiguousarray((img - bkg.back()).astype(np.float64))
        sources = sep.extract(sub, thresh=5.0, err=err_map)
        assert len(sources) >= 1


# ---------------------------------------------------------------------------
# sep.sum_circle — circular aperture photometry
# ---------------------------------------------------------------------------

class TestSepSumCircle:
    """sum_circle returns (flux, fluxerr, flag) for each aperture."""

    def _sources_and_sub(self, seed=42):
        import sep
        img = _c_contiguous(_make_image(nstars=3, star_flux=10000.0, seed=seed))
        bkg = sep.Background(img)
        sub = np.ascontiguousarray((img - bkg.back()).astype(np.float64))
        sources = sep.extract(sub, thresh=5.0, err=bkg.globalrms)
        return sub, sources, bkg.globalrms

    def test_returns_three_arrays(self):
        import sep
        sub, sources, rms = self._sources_and_sub()
        result = sep.sum_circle(sub, sources["x"], sources["y"], 5.0, err=rms)
        assert len(result) == 3

    def test_flux_positive(self):
        import sep
        sub, sources, rms = self._sources_and_sub()
        flux, _, _ = sep.sum_circle(sub, sources["x"], sources["y"], 5.0, err=rms)
        assert np.all(flux > 0)

    def test_fluxerr_positive(self):
        import sep
        sub, sources, rms = self._sources_and_sub()
        _, fluxerr, _ = sep.sum_circle(sub, sources["x"], sources["y"], 5.0, err=rms)
        assert np.all(fluxerr > 0)

    def test_flag_is_integer_array(self):
        import sep
        sub, sources, rms = self._sources_and_sub()
        _, _, flag = sep.sum_circle(sub, sources["x"], sources["y"], 5.0, err=rms)
        assert np.issubdtype(flag.dtype, np.integer)

    def test_larger_aperture_has_more_flux(self):
        """Larger aperture should enclose more flux for an isolated star."""
        import sep
        sub, sources, rms = self._sources_and_sub()
        flux_small, _, _ = sep.sum_circle(sub, sources["x"], sources["y"], 2.0, err=rms)
        flux_large, _, _ = sep.sum_circle(sub, sources["x"], sources["y"], 6.0, err=rms)
        assert np.all(flux_large >= flux_small)

    def test_clean_apertures_have_zero_flag(self):
        """Bright isolated stars well inside the image should have flag==0."""
        import sep
        sub, sources, rms = self._sources_and_sub()
        _, _, flag = sep.sum_circle(sub, sources["x"], sources["y"], 4.0, err=rms)
        assert np.all(flag == 0)


