class TestSepSumCircann:
    """sum_circann measures flux in an annulus — used for local sky estimation."""

    def _sources_and_sub(self):
        import sep
        img = _c_contiguous(_make_image(nstars=3, star_flux=10000.0))
        bkg = sep.Background(img)
        sub = np.ascontiguousarray((img - bkg.back()).astype(np.float64))
        sources = sep.extract(sub, thresh=5.0, err=bkg.globalrms)
        return sub, sources, bkg.globalrms

    def test_returns_three_arrays(self):
        import sep
        sub, sources, rms = self._sources_and_sub()
        result = sep.sum_circann(sub, sources["x"], sources["y"], 5.0, 9.0, err=rms)
        assert len(result) == 3

    def test_annulus_flux_finite(self):
        import sep
        sub, sources, rms = self._sources_and_sub()
        flux, fluxerr, _ = sep.sum_circann(sub, sources["x"], sources["y"], 5.0, 9.0, err=rms)
        assert np.all(np.isfinite(flux))
        assert np.all(np.isfinite(fluxerr))

    def test_outer_gt_inner_required(self):
        """rout must be > rin; we verify the call succeeds."""
        import sep
        sub, sources, rms = self._sources_and_sub()
        flux, _, _ = sep.sum_circann(sub, sources["x"], sources["y"], 3.0, 7.0, err=rms)
        assert isinstance(flux, np.ndarray)


