class TestSepKronRadius:
    """kron_radius measures the first-moment Kron radius of each detected source."""

    def _sources_and_sub(self):
        import sep
        img = _c_contiguous(_make_image(nstars=3, star_flux=10000.0))
        bkg = sep.Background(img)
        sub = np.ascontiguousarray((img - bkg.back()).astype(np.float64))
        sources = sep.extract(sub, thresh=5.0, err=bkg.globalrms)
        return sub, sources

    def test_returns_two_arrays(self):
        import sep
        sub, sources = self._sources_and_sub()
        result = sep.kron_radius(sub, sources["x"], sources["y"],
                                  sources["a"], sources["b"], sources["theta"], 6.0)
        assert len(result) == 2

    def test_kron_radius_positive(self):
        import sep
        sub, sources = self._sources_and_sub()
        kr, _ = sep.kron_radius(sub, sources["x"], sources["y"],
                                 sources["a"], sources["b"], sources["theta"], 6.0)
        assert np.all(kr > 0)

    def test_flag_is_integer(self):
        import sep
        sub, sources = self._sources_and_sub()
        _, kflag = sep.kron_radius(sub, sources["x"], sources["y"],
                                    sources["a"], sources["b"], sources["theta"], 6.0)
        assert np.issubdtype(kflag.dtype, np.integer)


