class TestSepFluxRadius:
    """flux_radius computes the radius enclosing a given fraction of the flux."""

    def _sources_and_sub(self):
        import sep
        img = _c_contiguous(_make_image(nstars=3, star_flux=10000.0))
        bkg = sep.Background(img)
        sub = np.ascontiguousarray((img - bkg.back()).astype(np.float64))
        sources = sep.extract(sub, thresh=5.0, err=bkg.globalrms)
        return sub, sources

    def test_returns_two_arrays(self):
        import sep
        sub, sources = self._sources_and_sub()
        result = sep.flux_radius(sub, sources["x"], sources["y"],
                                  6.0 * sources["a"], 0.5)
        assert len(result) == 2

    def test_half_light_radius_positive(self):
        import sep
        sub, sources = self._sources_and_sub()
        fr, _ = sep.flux_radius(sub, sources["x"], sources["y"],
                                 6.0 * sources["a"], 0.5)
        assert np.all(fr > 0)

    def test_larger_fraction_gives_larger_radius(self):
        """90% flux radius must be >= 50% flux radius."""
        import sep
        sub, sources = self._sources_and_sub()
        fr50, _ = sep.flux_radius(sub, sources["x"], sources["y"],
                                   8.0 * sources["a"], 0.5)
        fr90, _ = sep.flux_radius(sub, sources["x"], sources["y"],
                                   8.0 * sources["a"], 0.9)
        assert np.all(fr90 >= fr50 - 1e-6)


# ---------------------------------------------------------------------------
# sep.winpos — windowed centroid refinement
# ---------------------------------------------------------------------------

class TestSepWinpos:
    """winpos refines source centroids using a Gaussian window."""

    def _sources_and_sub(self):
        import sep
        img = _c_contiguous(_make_image(nstars=3, star_flux=10000.0))
        bkg = sep.Background(img)
        sub = np.ascontiguousarray((img - bkg.back()).astype(np.float64))
        sources = sep.extract(sub, thresh=5.0, err=bkg.globalrms)
        return sub, sources

    def test_returns_three_arrays(self):
        import sep
        sub, sources = self._sources_and_sub()
        result = sep.winpos(sub, sources["x"], sources["y"], 2.0)
        assert len(result) == 3

    def test_refined_positions_close_to_initial(self):
        """Windowed centroids should be within 1 pixel of the initial detection."""
        import sep
        sub, sources = self._sources_and_sub()
        xwin, ywin, _ = sep.winpos(sub, sources["x"], sources["y"], 2.0)
        assert np.all(np.abs(xwin - sources["x"]) < 1.0)
        assert np.all(np.abs(ywin - sources["y"]) < 1.0)

    def test_flag_dtype(self):
        import sep
        sub, sources = self._sources_and_sub()
        _, _, flag = sep.winpos(sub, sources["x"], sources["y"], 2.0)
        assert np.issubdtype(flag.dtype, np.integer)


# ---------------------------------------------------------------------------
# sep.ellipse_coeffs / sep.ellipse_axes — geometry roundtrip
# ---------------------------------------------------------------------------

class TestSepEllipseGeometry:
    """ellipse_coeffs and ellipse_axes are inverse operations."""

    def test_ellipse_coeffs_returns_three_floats(self):
        import sep
        cxx, cyy, cxy = sep.ellipse_coeffs(2.0, 1.5, 0.3)
        # sep returns 0-d numpy arrays; check they are scalar-like floats
        assert float(cxx) > 0
        assert float(cyy) > 0
        assert np.isfinite(float(cxy))

    def test_roundtrip_a(self):
        import sep
        a, b, theta = 2.1, 1.8, 0.5
        cxx, cyy, cxy = sep.ellipse_coeffs(a, b, theta)
        a2, b2, theta2 = sep.ellipse_axes(cxx, cyy, cxy)
        assert a2 == pytest.approx(a, abs=1e-5)

    def test_roundtrip_b(self):
        import sep
        a, b, theta = 3.0, 2.0, 0.0
        cxx, cyy, cxy = sep.ellipse_coeffs(a, b, theta)
        a2, b2, theta2 = sep.ellipse_axes(cxx, cyy, cxy)
        assert b2 == pytest.approx(b, abs=1e-5)

    def test_circle_gives_equal_cxx_cyy(self):
        """For a circle (a==b), cxx should equal cyy."""
        import sep
        cxx, cyy, cxy = sep.ellipse_coeffs(2.0, 2.0, 0.0)
        assert cxx == pytest.approx(cyy, rel=1e-5)

    def test_ellipse_axes_from_source_params(self):
        """Roundtrip using real source cxx/cyy/cxy fields."""
        import sep
        img = _c_contiguous(_make_image(nstars=3, star_flux=10000.0))
        bkg = sep.Background(img)
        sub = np.ascontiguousarray((img - bkg.back()).astype(np.float64))
        sources = sep.extract(sub, thresh=5.0, err=bkg.globalrms)
        a2, b2, theta2 = sep.ellipse_axes(
            float(sources["cxx"][0]),
            float(sources["cyy"][0]),
            float(sources["cxy"][0]),
        )
        assert a2 == pytest.approx(float(sources["a"][0]), abs=1e-4)


