class TestSepGetSetPixstack:
    """get_extract_pixstack mirrors the value set by set_extract_pixstack."""

    def test_get_returns_integer(self):
        import sep
        val = sep.get_extract_pixstack()
        assert isinstance(val, int)

    def test_set_then_get_roundtrip(self):
        import sep
        sep.set_extract_pixstack(123456)
        assert sep.get_extract_pixstack() == 123456
        # restore a sensible default
        sep.set_extract_pixstack(300000)

    def test_set_large_value(self):
        import sep
        sep.set_extract_pixstack(2_000_000)
        assert sep.get_extract_pixstack() == 2_000_000
        sep.set_extract_pixstack(300000)

    def test_pixstack_affects_extract(self):
        """set_extract_pixstack should not break a normal extraction."""
        import sep
        sep.set_extract_pixstack(500000)
        img = _c_contiguous(_make_image(nstars=3))
        bkg = sep.Background(img)
        sub = np.ascontiguousarray((img - bkg.back()).astype(np.float64))
        sources = sep.extract(sub, thresh=5.0, err=bkg.globalrms)
        assert len(sources) >= 1
        sep.set_extract_pixstack(300000)


