# ---------------------------------------------------------------------------
# PyZOGY.util end-to-end pattern
# ---------------------------------------------------------------------------

class TestPyZOGYUtilPattern:
    """Reproduce the exact sep usage from PyZOGY/util.py lines 38, 103-105."""

    def _make_masked_image(self, seed=0):
        """Return (data, mask) pair as PyZOGY.util expects."""
        rng = np.random.default_rng(seed)
        data = rng.normal(1000.0, 20.0, (64, 64)).astype(np.float32)
        # add a few bright stars
        for cx, cy in [(15, 15), (45, 45), (30, 30)]:
            yy, xx = np.mgrid[0:64, 0:64]
            data += 8000.0 * np.exp(-((xx - cx) ** 2 + (yy - cy) ** 2) / 8.0)
        mask = np.zeros((64, 64), dtype=bool)
        return data, mask

    def test_background_byteswap_newbyteorder(self):
        """PyZOGY.util line 38: converts non-native byte order before Background.
        In numpy 2.x the correct idiom is astype(dtype.newbyteorder('=')).
        """
        import sep
        data, _ = self._make_masked_image()
        # Convert to native byte order (numpy 2.x compatible)
        safe = np.ascontiguousarray(data.astype(data.dtype.newbyteorder('=')))
        bkg = sep.Background(safe)
        assert bkg.globalrms > 0.0

    def test_set_pixstack_then_extract_science(self):
        """PyZOGY.util lines 103-104: set pixstack, then extract science sources."""
        import sep
        sep.set_extract_pixstack(300000)
        data, mask = self._make_masked_image(seed=1)
        science_std = np.std(data[:10, :10])  # rough sky noise
        sources = sep.extract(
            np.ascontiguousarray(data.astype(np.float64)),
            thresh=5.0,
            err=science_std,
            mask=np.ascontiguousarray(mask),
        )
        assert len(sources) >= 1

    def test_extract_science_and_reference_both_work(self):
        """PyZOGY.util lines 104-105: extract from science AND reference."""
        import sep
        sci_data, sci_mask = self._make_masked_image(seed=2)
        ref_data, ref_mask = self._make_masked_image(seed=3)
        sci_std = float(np.std(sci_data[:8, :8]))
        ref_std = float(np.std(ref_data[:8, :8]))
        sci_sources = sep.extract(
            np.ascontiguousarray(sci_data.astype(np.float64)),
            thresh=5.0, err=sci_std,
            mask=np.ascontiguousarray(sci_mask),
        )
        ref_sources = sep.extract(
            np.ascontiguousarray(ref_data.astype(np.float64)),
            thresh=5.0, err=ref_std,
            mask=np.ascontiguousarray(ref_mask),
        )
        assert len(sci_sources) >= 1
        assert len(ref_sources) >= 1

    def test_sources_have_x_y_a_b_theta(self):
        """Fields needed by PyZOGY for PSF matching must all be present."""
        import sep
        data, mask = self._make_masked_image(seed=4)
        sources = sep.extract(
            np.ascontiguousarray(data.astype(np.float64)),
            thresh=5.0, err=50.0,
            mask=np.ascontiguousarray(mask),
        )
        for field in ("x", "y", "a", "b", "theta"):
            assert field in sources.dtype.names
